import{_t as e,it as t,n,rt as r}from"./chunks/framework.uM88Qy9F.js";var i=JSON.parse(`{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1794163917000}`),a={name:`faq.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h1><p>本页说明运行、认证、权限与接口联调中的常见问题，适用于开发与运维排查。</p><h2 id="启动与环境" tabindex="-1">启动与环境 <a class="header-anchor" href="#启动与环境" aria-label="Permalink to “启动与环境”">​</a></h2><h3 id="后端与前端使用哪些端口" tabindex="-1">后端与前端使用哪些端口？ <a class="header-anchor" href="#后端与前端使用哪些端口" aria-label="Permalink to “后端与前端使用哪些端口？”">​</a></h3><p>后端 HTTP <code>9710</code>、gRPC <code>9711</code>（只监听本机），前端开发服务器 <code>9100</code>。以 <code>appsettings.json</code> 的 <code>Kestrel:Endpoints</code> 与 <code>frontend/.env</code> 的 <code>VITE_PORT</code> 为准。</p><h3 id="构建或测试报框架相关的错" tabindex="-1">构建或测试报框架相关的错 <a class="header-anchor" href="#构建或测试报框架相关的错" aria-label="Permalink to “构建或测试报框架相关的错”">​</a></h3><p>后端以源码引用同级检出的 XiHan.Framework（<code>../../XiHan.Framework/framework/src</code>，相对 <code>backend/</code>），并锁定在 <code>backend/props/framework.props</code> 的 <code>XiHanFrameworkCommit</code>。同级找不到 <code>framework/src</code> 时构建会自动改用 NuGet 包，公开面可能与锁定提交不一致。把框架检出到锁定提交；框架在别处时加 <code>-p:XiHanFrameworkSrc=&lt;检出&gt;/framework/src/</code>。见<a href="./dev-environment#框架检出">开发环境</a>。</p><h3 id="frameworkpintests-失败" tabindex="-1"><code>FrameworkPinTests</code> 失败 <a class="header-anchor" href="#frameworkpintests-失败" aria-label="Permalink to “FrameworkPinTests 失败”">​</a></h3><p>同级框架检出没有 <code>framework/src</code>，或 HEAD 不在锁定提交上。把框架检出到 <code>XiHanFrameworkCommit</code> 指定的提交；其他测试不受影响。</p><h3 id="宿主启动后立即退出" tabindex="-1">宿主启动后立即退出 <a class="header-anchor" href="#宿主启动后立即退出" aria-label="Permalink to “宿主启动后立即退出”">​</a></h3><ul><li>日志有 <code>RUNTIME_VALIDATION_001</code>：没有配置 <code>XiHan:Bindings:db</code>。</li><li>日志有 <code>Startup aborted: schema upgrade failed</code>：表结构升级脚本执行失败，看后面的错误码与信息；修好后重启即可，台账里记着执行到哪。</li><li>JWT 密钥或签名地址密钥缺失、不足 32 字节：非 Development 环境必须配 <code>XiHan:Security:Jwt:Secret</code> 与 <code>XiHan:ObjectStorage:SignedUrls:Secret</code>。</li><li>框架节写了空的 <code>[]</code> / <code>{}</code>：整项删掉，见<a href="./configuration#文件与优先级">配置参考</a>。</li></ul><h3 id="表已创建-但无法以-superadmin-登录" tabindex="-1">表已创建，但无法以 <code>superadmin</code> 登录 <a class="header-anchor" href="#表已创建-但无法以-superadmin-登录" aria-label="Permalink to “表已创建，但无法以 superadmin 登录”">​</a></h3><p>种子不随启动执行，要单独运行一次：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend/src/XiHan.BasicApp.Host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --launch-profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Development</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> seed</span></span></code></pre></div><h3 id="前端提示跨域错误" tabindex="-1">前端提示跨域错误 <a class="header-anchor" href="#前端提示跨域错误" aria-label="Permalink to “前端提示跨域错误”">​</a></h3><p>开发时前端经 Vite 代理访问后端，与后端同源，不应出现跨域。出现了说明 <code>VITE_API_BASE_URL</code> 被设成了别的源，留空即可。部署推荐同源；前端放在别的源时，在 <code>BasicApp:Cors:AllowedOrigins</code> 列出它，见<a href="./deployment#前端-构建与部署">部署</a>。</p><h3 id="是否需要-redis" tabindex="-1">是否需要 Redis？ <a class="header-anchor" href="#是否需要-redis" aria-label="Permalink to “是否需要 Redis？”">​</a></h3><p>不需要。不配连接时缓存与消息走框架的进程内实现，开发与单实例部署零外部依赖。多实例部署时配上 Redis（与 RabbitMQ），宿主自动装上对应 Provider，缓存与消息跨实例共享，实时推送也跨实例，见<a href="./deployment#多实例部署">部署</a>。</p><h2 id="认证与令牌" tabindex="-1">认证与令牌 <a class="header-anchor" href="#认证与令牌" aria-label="Permalink to “认证与令牌”">​</a></h2><h3 id="初始超级管理员账号是什么" tabindex="-1">初始超级管理员账号是什么？ <a class="header-anchor" href="#初始超级管理员账号是什么" aria-label="Permalink to “初始超级管理员账号是什么？”">​</a></h3><p>开发环境是 <code>superadmin</code> / <code>SuperAdmin@123</code>，由 <code>seed</code> 写入，密码写在 <code>appsettings.Development.json</code> 的 <code>BasicApp:Seed:SuperAdminPassword</code>。别的环境必须配这一项，否则 <code>seed</code> 失败（<code>IDENTITY_VALIDATION_026</code>）。首次登录后请修改密码。</p><h3 id="命令行调用登录接口时如何处理验证码" tabindex="-1">命令行调用登录接口时如何处理验证码？ <a class="header-anchor" href="#命令行调用登录接口时如何处理验证码" aria-label="Permalink to “命令行调用登录接口时如何处理验证码？”">​</a></h3><p>图形验证码缺省开启（<code>BasicApp:Auth:CaptchaEnabled</code>）。先调 <code>POST /api/auth:captcha</code> 取 <code>captchaId</code> 与图片，或在本机配置里临时关掉。</p><h3 id="登录提示尝试过于频繁" tabindex="-1">登录提示尝试过于频繁 <a class="header-anchor" href="#登录提示尝试过于频繁" aria-label="Permalink to “登录提示尝试过于频繁”">​</a></h3><p>登录节流：同一账号同一地址每分钟 5 次失败、同一地址跨账号 30 次（<code>BasicApp:Auth:LoginThrottle*</code>），超限返回 <code>IDENTITY_UNAVAILABLE_001</code> 并带 <code>retryAfter</code>。连续失败达到 <code>MaxFailedAccessAttempts</code> 还会锁定账号。</p><h3 id="接口返回-403-code-是-identity-denied-002" tabindex="-1">接口返回 403，<code>code</code> 是 <code>IDENTITY_DENIED_002</code> <a class="header-anchor" href="#接口返回-403-code-是-identity-denied-002" aria-label="Permalink to “接口返回 403，code 是 IDENTITY_DENIED_002”">​</a></h3><p>会话被锁定，<code>details.reason</code> 说明原因：<code>ScreenLock</code> 是锁屏，前端进锁屏界面，调 <code>auth.unlock</code> 解锁；<code>PasswordChangeRequired</code> 是强制改密（系统参数 <code>identity.password</code>），调 <code>profile.change-password</code> 改完即解开。</p><h3 id="授予权限后是否需要重新登录" tabindex="-1">授予权限后是否需要重新登录？ <a class="header-anchor" href="#授予权限后是否需要重新登录" aria-label="Permalink to “授予权限后是否需要重新登录？”">​</a></h3><ul><li>授予、Deny、委托：判定时实时查（规则缓存 60 秒、写入方即时失效），不用重新登录。</li><li>角色指派：判定用的角色取「令牌里的角色」与「有效指派」的交集，解除立即生效；新增的角色要等下一次刷新令牌才进令牌。</li><li>前端菜单与按钮：刷新令牌后会重新取 <code>auth.permissions</code>。</li></ul><h3 id="切换租户是否会结束原来的会话" tabindex="-1">切换租户是否会结束原来的会话？ <a class="header-anchor" href="#切换租户是否会结束原来的会话" aria-label="Permalink to “切换租户是否会结束原来的会话？”">​</a></h3><p>不会。<code>auth.switch-tenant</code> 续用同一个会话，只换令牌；前端换完令牌整页重建。</p><h2 id="权限与菜单" tabindex="-1">权限与菜单 <a class="header-anchor" href="#权限与菜单" aria-label="Permalink to “权限与菜单”">​</a></h2><h3 id="新增页面未出现在菜单中" tabindex="-1">新增页面未出现在菜单中 <a class="header-anchor" href="#新增页面未出现在菜单中" aria-label="Permalink to “新增页面未出现在菜单中”">​</a></h3><ol><li>页面要登记在包的 <code>&lt;包&gt;Pages.cs</code> 里，并重新执行 <code>seed</code>（<code>access.menus</code> 种子从页面登记对齐菜单）。</li><li>当前主体要有页面登记里的权限码；租户主体还要被套餐白名单放行。</li><li>页面的作用侧要和当前主体一致（平台 / 租户）。</li><li>页面属于可选模块时，模块要开着（<code>BasicApp:Modules:&lt;名&gt;:Enabled</code>）。</li></ol><h3 id="菜单可见但页面显示-404" tabindex="-1">菜单可见但页面显示 404 <a class="header-anchor" href="#菜单可见但页面显示-404" aria-label="Permalink to “菜单可见但页面显示 404”">​</a></h3><p>前端按组件路径精确解析：页面路由 <code>/identity/users</code> 的组件是 <code>identity/users/index</code>，对应 <code>src/modules/identity/views/users/index.vue</code>。文件不在这个位置就落 404 兜底，控制台报错。<code>pnpm modules:check</code> 会检查撞键。</p><h3 id="已授予权限码但接口仍返回-403" tabindex="-1">已授予权限码但接口仍返回 403 <a class="header-anchor" href="#已授予权限码但接口仍返回-403" aria-label="Permalink to “已授予权限码但接口仍返回 403”">​</a></h3><p>按顺序查：</p><ol><li>有没有 Deny（角色或用户直授上的拒绝压过授予）；</li><li>授予或指派是不是过期了、还没生效；</li><li>租户套餐白名单有没有这个码（套餐门控）；</li><li>权限码的作用侧与当前主体是否一致；</li><li>有没有挂权限条件（ABAC）且这次请求不满足：查「条件命中」日志；</li><li>访问策略是否拦截：查「条件命中」与登录日志。</li></ol><h3 id="列表字段为空或显示为星号" tabindex="-1">列表字段为空或显示为星号 <a class="header-anchor" href="#列表字段为空或显示为星号" aria-label="Permalink to “列表字段为空或显示为星号”">​</a></h3><p>字段安全规则命中了：读取方式为隐藏的字段不返回值，部分脱敏的字段打码；受保护的字段也不能筛选和排序。见<a href="./backend/data-permission">数据权限与字段安全</a>。</p><h2 id="接口与联调" tabindex="-1">接口与联调 <a class="header-anchor" href="#接口与联调" aria-label="Permalink to “接口与联调”">​</a></h2><h3 id="如何确定操作的-http-路由" tabindex="-1">如何确定操作的 HTTP 路由 <a class="header-anchor" href="#如何确定操作的-http-路由" aria-label="Permalink to “如何确定操作的 HTTP 路由”">​</a></h3><p>路由完全由操作 ID 与请求形状推导：请求带 <code>id</code> 即实例级（<code>/{id}</code>），带分页对象这类嵌套对象的 <code>list</code> 走 POST，<code>get</code> 与声明了 <code>ReadOnly</code> 且没有嵌套对象的查询动词走 GET。以 <code>/openapi.json</code> 为准，见<a href="./api-guide#路由推导">接口对接指南</a>。</p><h3 id="批量删除如何传递-id" tabindex="-1">批量删除如何传递 ID <a class="header-anchor" href="#批量删除如何传递-id" aria-label="Permalink to “批量删除如何传递 ID”">​</a></h3><p>批量删除是 <code>DELETE /api/&lt;资源&gt;?ids=&lt;id1&gt;&amp;ids=&lt;id2&gt;</code>，响应是逐项结果 <code>{ succeeded, failed }</code>。</p><h3 id="时间显示相差若干小时" tabindex="-1">时间显示相差若干小时 <a class="header-anchor" href="#时间显示相差若干小时" aria-label="Permalink to “时间显示相差若干小时”">​</a></h3><p>接口一律 UTC（带 <code>Z</code>），服务端不做时区换算，换算是客户端的事。前端按偏好设置里的应用时区显示（缺省 <code>Asia/Shanghai</code>，顶栏的时区切换器可改），不看浏览器所在的时区，见<a href="./frontend/i18n#时区">国际化与时区</a>。自己对接时不要把带 <code>Z</code> 的时间当本地时间解析。</p><h3 id="修改后端-dto-后前端类型未更新" tabindex="-1">修改后端 DTO 后前端类型未更新 <a class="header-anchor" href="#修改后端-dto-后前端类型未更新" aria-label="Permalink to “修改后端 DTO 后前端类型未更新”">​</a></h3><p>前端契约是生成物：后端导出 <code>openapi.json</code>，前端 <code>pnpm gen:contracts</code> 重新生成，两者同一提交。CI 会重新生成并比对，不一致即失败。见<a href="./frontend/request">契约与请求</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./getting-started">快速开始</a> · <a href="./api-guide">接口对接指南</a> · <a href="./configuration">配置参考</a></li></ul>`,52)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};